package authz

import (
	"context"
	"fmt"
)

type contextKey string

// NamespacesKey is the context key used to pass accessible namespaces from
// authorization middleware to server methods.
const NamespacesKey contextKey = "accessible_namespaces"

type Verifier interface {
	IsAllowed(ctx context.Context, input map[string]any) (bool, error)
	Namespaces(ctx context.Context, input map[string]any) ([]string, error)
	Shutdown(ctx context.Context) error
}

// ContextWithNamespaces stores the namespaces accessible to the request.
func ContextWithNamespaces(ctx context.Context, namespaces []string) context.Context {
	copy := append([]string{}, namespaces...)
	return context.WithValue(ctx, NamespacesKey, copy)
}

// NamespacesFromContext retrieves the accessible namespaces for a request.
// It returns nil when no namespace authorization result was stored.
func NamespacesFromContext(ctx context.Context) []string {
	namespaces, _ := ctx.Value(NamespacesKey).([]string)
	return namespaces
}

// FormatNamespaces validates and converts an authorization result to a list of
// namespace keys. OPA returns JSON arrays as []interface{} values.
func FormatNamespaces(result any) ([]string, error) {
	var values []any
	switch result := result.(type) {
	case []string:
		values = make([]any, len(result))
		for i := range result {
			values[i] = result[i]
		}
	case []any:
		values = result
	default:
		return nil, fmt.Errorf("viewable namespaces decision returned %T, expected a list of strings", result)
	}

	namespaces := make([]string, 0, len(values))
	seen := make(map[string]struct{}, len(values))
	for i, value := range values {
		namespace, ok := value.(string)
		if !ok {
			return nil, fmt.Errorf("viewable namespaces decision item %d returned %T, expected a string", i, value)
		}
		if namespace == "" {
			return nil, fmt.Errorf("viewable namespaces decision item %d is empty", i)
		}
		if _, ok := seen[namespace]; ok {
			continue
		}
		seen[namespace] = struct{}{}
		namespaces = append(namespaces, namespace)
	}

	return namespaces, nil
}
}

// ListNamespaces lists all namespaces
func (s *Server) ListNamespaces(ctx context.Context, r *flipt.ListNamespaceRequest) (*flipt.NamespaceList, error) {
	s.logger.Debug("list namespaces", zap.Stringer("request", r))

	ref := storage.ReferenceRequest{Reference: storage.Reference(r.Reference)}
	results, err := s.store.ListNamespaces(ctx, storage.ListWithParameters(ref, r))
	if err != nil {
		return nil, err
	}

	namespaces := results.Results
	accessibleNamespaces := authz.NamespacesFromContext(ctx)
	var total uint64
	if accessibleNamespaces != nil {
		accessible := make(map[string]struct{}, len(accessibleNamespaces))
		for _, namespace := range accessibleNamespaces {
			accessible[namespace] = struct{}{}
		}

		filtered := make([]*flipt.Namespace, 0, len(namespaces))
		for _, namespace := range namespaces {
			if _, ok := accessible[namespace.Key]; ok {
				filtered = append(filtered, namespace)
			}
		}
		namespaces = filtered
		total = uint64(len(accessibleNamespaces))
	} else {
		total, err = s.store.CountNamespaces(ctx, ref)
		if err != nil {
			return nil, err
		}
	}

	resp := flipt.NamespaceList{Namespaces: namespaces}

	resp.TotalCount = int32(total)
	resp.NextPageToken = results.NextPageToken

	s.logger.Debug("list namespaces", zap.Stringer("response", &resp))
	return &resp, nil
}

// CreateNamespace creates a namespace
func (s *Server) CreateNamespace(ctx context.Context, r *flipt.CreateNamespaceRequest) (*flipt.Namespace, error) {
	s.logger.Debug("create namespace", zap.Stringer("request", r))
	namespace, err := s.store.CreateNamespace(ctx, r)
	s.logger.Debug("create namespace", zap.Stringer("response", namespace))
	return namespace, err
}

// UpdateNamespace updates an existing namespace
func (s *Server) UpdateNamespace(ctx context.Context, r *flipt.UpdateNamespaceRequest) (*flipt.Namespace, error) {
	s.logger.Debug("update namespace", zap.Stringer("request", r))
	namespace, err := s.store.UpdateNamespace(ctx, r)
	s.logger.Debug("update namespace", zap.Stringer("response", namespace))
	return namespace, err
}

